import { useState } from "react";
export function App() {
  const [status, setStatus] = useState("idle");
  return <button data-testid="async-swallow" onClick={async () => { try { await Promise.resolve(); setStatus("fixed"); } catch { setStatus("error"); } }}>Async handler swallows error</button>;
}
